// Silent Background Sync: Updates all related dropdowns, tables & counters while preserving unsaved form selections!
async function softSyncAdmin() {
  try {
    const keepIds = ['catName', 'catIcon', 'catSort', 'catStatus', 'prodName', 'prodCat', 'prodIcon', 'prodPrice', 'prodDesc', 'prodFullDesc', 'upProdId', 'upText'];
    const saved = {};
    keepIds.forEach(fid => {
      const el = document.getElementById(fid);
      if (el) saved[fid] = el.value;
    });

    const res  = await fetch('admin.php?_t=' + Date.now(), { cache: 'no-store' });
    const html = await res.text();
    const doc  = new DOMParser().parseFromString(html, 'text/html');

    // Sync all related sections, dropdowns (<select>) & tables silently
    const syncIds = ['sec-dashboard', 'sec-categories', 'sec-products', 'sec-upload', 'sec-deposits', 'sec-users', 'sec-orders', 'drawer'];
    syncIds.forEach(id => {
      const curEl = document.getElementById(id);
      const newEl = doc.getElementById(id);
      if (curEl && newEl) {
        curEl.innerHTML = newEl.innerHTML;
      }
    });

    // Also sync Edit Product modal category dropdown so newly created categories appear immediately!
    const curEpCat = document.getElementById('epCat');
    const newEpCat = doc.getElementById('epCat');
    if (curEpCat && newEpCat) {
      const prevEpVal = curEpCat.value;
      curEpCat.innerHTML = newEpCat.innerHTML;
      if (prevEpVal && Array.from(curEpCat.options).some(o => o.value === prevEpVal)) {
        curEpCat.value = prevEpVal;
      }
    }

    // Restore in-progress form fields cleanly
    keepIds.forEach(fid => {
      const el = document.getElementById(fid);
      if (!el || saved[fid] === undefined) return;
      if (el.tagName === 'SELECT') {
        if (saved[fid] && Array.from(el.options).some(o => o.value === saved[fid])) {
          el.value = saved[fid];
        }
      } else if (saved[fid] !== '') {
        el.value = saved[fid];
      }
    });

    // Re-bind Create Category & Create Product Icon Pickers after section re-renders
    mountCatIconPicker('createCatPicker', 'catIcon', 'catName', { defaultFallbackName: 'Category' });
    mountCatIconPicker('createProdPicker', 'prodIcon', 'prodName', { allowDefault: true, catSelectId: 'prodCat', defaultFallbackName: 'Product' });
    bindProductPickerListeners();
    updateCatSlugPreview();

    // Keep active menu & dock button highlighted cleanly
    const activeSec = document.querySelector('.sec.active');
    if (activeSec) {
      const tabId = activeSec.id.replace('sec-', '');
      document.querySelectorAll('#drawer .d-btn, .mob-dock .dock-btn').forEach(b => b.classList.remove('active'));
      const navBtn = document.getElementById('nav-' + tabId);
      const dockBtn = document.getElementById('m-' + tabId);
      if (navBtn) navBtn.classList.add('active');
      if (dockBtn) dockBtn.classList.add('active');
    }
  } catch (e) {}
}

// Helper to smoothly animate & remove a row AND sync all related dropdowns/tables!
function removeRowSmoothly(rowEl) {
  if (rowEl) {
    rowEl.style.transition = 'all 0.28s cubic-bezier(.4,0,.2,1)';
    rowEl.style.opacity    = '0';
    rowEl.style.transform  = 'translateX(24px) scale(0.96)';
    setTimeout(() => { rowEl.remove(); softSyncAdmin(); }, 280);
  } else {
    softSyncAdmin();
  }
}

