  document.getElementById('balUserName').textContent = name;
  document.getElementById('balAmountInput').value = '';
  document.getElementById('balModal').classList.add('show');
}

async function submitBalAdjust() {
  const uid = document.getElementById('balUserId').value;
  const val = document.getElementById('balAmountInput').value.trim();
  if (!val) return toast('Enter an amount!', true);
  closeModal('balModal');
  const d = await post({ admin_action: 'adjust_balance', user_id: uid, amount: parseFloat(val) });
  if (d.success) toast(d.message);
  softSyncAdmin();
}

function filterAdminUsers(q) {
  const term = String(q || '').toLowerCase().replace('@', ' ').trim();
  document.querySelectorAll('#adminUsersTable tbody tr.user-row').forEach(tr => {
    const hay = tr.getAttribute('data-search') || '';
    tr.style.display = (!term || hay.includes(term)) ? '' : 'none';
  });
}

async function toggleBan(uid) {
  const d = await post({ admin_action: 'toggle_user_ban', user_id: uid });
  if (d.success) toast(d.message);
  softSyncAdmin();
}

async function viewDepScreenshot(depId) {
  startLoad();
  const d = await post({ admin_action: 'get_deposit_screenshot', deposit_id: depId });
  endLoad();
  if (!d.success || !d.deposit) return toast(d.error || 'Could not load screenshot', true);

  const dep = d.deposit;
  document.getElementById('scMetaBox').innerHTML = `
    <div style="display:flex;justify-content:space-between;margin-bottom:3px">
      <span><b>Method:</b> ${escCode(dep.method)}</span>
      <span><b>Amount:</b> <b style="color:var(--primary)">৳${Number(dep.amount).toFixed(2)}</b></span>
    </div>
    <div style="display:flex;justify-content:space-between">
      <span><b>Sender:</b> <span class="mono">${escCode(dep.sender_num || '-')}</span></span>
      <span><b>TrxID:</b> <span class="mono" style="font-weight:800">${escCode(dep.trx_id)}</span></span>
    </div>
  `;
  document.getElementById('scPreviewImg').src = dep.screenshot;

  const actBox = document.getElementById('scActionBtns');
  if (dep.status === 'pending') {
    actBox.innerHTML = `
      <button class="btn btn-success" style="flex:1;padding:8px" onclick="closeModal('screenModal');handleDep(${dep.id}, 'approve')"><i class="ri-check-line"></i> Approve Payment</button>
      <button class="btn btn-danger" style="flex:1;padding:8px" onclick="closeModal('screenModal');handleDep(${dep.id}, 'reject')"><i class="ri-close-line"></i> Reject</button>
    `;
  } else {
    actBox.innerHTML = `<button class="btn btn-outline" style="width:100%;padding:8px" onclick="closeModal('screenModal')">Close Preview (${String(dep.status).toUpperCase()})</button>`;
  }

  document.getElementById('screenModal').classList.add('show');
}

function copyOneClickAppSetup() {
  const sec = document.getElementById('setSmsSecret').value.trim();
  const url = '<?= htmlspecialchars(rtrim(SITE_URL, '/')) ?>/api.php?action=own_sms_sync';
  navigator.clipboard.writeText(url + '|' + sec);
  toast('1-Click Setup Code Copied! Paste inside MRMS AutoPay App.');
}

function buildBrandIconHtml(logoVal, size) {
  const v = String(logoVal || '').trim();
  if (isCatImgIcon(v)) {
    return `<img src="${escCode(v)}" alt="Logo" style="width:${size}px;height:${size}px;object-fit:contain;border-radius:6px;display:block">`;
  }
  return '<i class="ri-flashlight-fill"></i>';
}

function updateBrandPreview() {
  const nameEl = document.getElementById('setSiteName');
  const logoEl = document.getElementById('setSiteLogo');
  const pName = (nameEl && nameEl.value.trim()) ? nameEl.value.trim() : <?= json_encode(SITE_NAME, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP) ?>;
  const pLogo = logoEl ? logoEl.value.trim() : '';
  const prevBox = document.getElementById('setBrandPreviewBox');
  const prevName = document.getElementById('setBrandPreviewName');
  if (prevBox) prevBox.innerHTML = buildBrandIconHtml(pLogo, 24);
  if (prevName) prevName.textContent = pName;
}

function handleBrandLogoUpload(inputEl) {
  const f = inputEl && inputEl.files && inputEl.files[0];
  if (!f) return;
  const reader = new FileReader();
  reader.onload = () => {
    if (typeof reader.result !== 'string') return;
    const target = document.getElementById('setSiteLogo');
    if (!target) return;
    if (f.type === 'image/svg+xml' || reader.result.length < 18000) {
      target.value = reader.result;
      updateBrandPreview();
      return;
    }
    const img = new Image();
    img.onload = () => {
      const maxDim = 160;
      const scale = Math.min(1, maxDim / Math.max(img.width || maxDim, img.height || maxDim));
      const w = Math.max(1, Math.round((img.width || maxDim) * scale));
      const h = Math.max(1, Math.round((img.height || maxDim) * scale));
      const cvs = document.createElement('canvas');
      cvs.width = w; cvs.height = h;
      cvs.getContext('2d').drawImage(img, 0, 0, w, h);
      target.value = cvs.toDataURL('image/png');
      updateBrandPreview();
    };
    img.onerror = () => { target.value = reader.result; updateBrandPreview(); };
    img.src = reader.result;
  };
  reader.readAsDataURL(f);
}

function resetSiteLogo() {
  const logoEl = document.getElementById('setSiteLogo');
  const fileEl = document.getElementById('siteLogoFile');
  if (logoEl) logoEl.value = '';
  if (fileEl) fileEl.value = '';
  updateBrandPreview();
}

function applyLiveBrandToAdmin(siteName, siteLogo) {
  const cleanName = String(siteName || '').trim() || <?= json_encode(SITE_NAME, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP) ?>;
  const cleanLogo = String(siteLogo || '').trim();
  document.title = cleanName + ' — Admin Pro';
  document.querySelectorAll('.brand-title, .splash-title').forEach(el => {
    el.textContent = el.classList.contains('splash-title') ? (cleanName + ' Admin') : cleanName;
  });
  document.querySelectorAll('.navbar .brand-ico, .drawer .brand-ico').forEach(el => {
    el.innerHTML = buildBrandIconHtml(cleanLogo, 22);
  });
  const fav = document.getElementById('siteFavicon');
  if (fav) fav.href = isCatImgIcon(cleanLogo) ? cleanLogo : '';
}

async function saveSettings() {
  const siteName = document.getElementById('setSiteName') ? document.getElementById('setSiteName').value.trim() : '';
  const siteLogo = document.getElementById('setSiteLogo') ? document.getElementById('setSiteLogo').value.trim() : '';
  const d = await post({
    admin_action: 'save_settings',
    site_name: siteName,
    site_logo: siteLogo,
    bkash_status: document.getElementById('setBkashStatus').value,
    bkash_number: document.getElementById('setBkash').value,
    nagad_status: document.getElementById('setNagadStatus').value,
    nagad_number: document.getElementById('setNagad').value,
    binance_status: document.getElementById('setBinanceStatus').value,
    binance_id: document.getElementById('setBinance').value,
    binance_rate: document.getElementById('setBinanceRate').value,
    binance_api_key: document.getElementById('setBinanceApiKey').value,
    binance_api_secret: document.getElementById('setBinanceApiSecret').value,
    sms_sync_secret: document.getElementById('setSmsSecret').value,
    min_deposit: document.getElementById('setMinDep').value,
    support_link: document.getElementById('setSupport').value,
    site_notice: document.getElementById('setNotice').value,
    google_client_id: document.getElementById('setGoogleId').value
  });
  if (d.success) {
    applyLiveBrandToAdmin(siteName, siteLogo);
    updateBrandPreview();
    toast(d.message);
  } else {
    toast(d.error || 'Failed to save settings!', true);
  }
}
</script>
